use pulldown_cmark::{Alignment, Event, Options, Parser, Tag, TagEnd};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Ink {
    Plain,
    Bold,
    Italic,
    Strike,
    Code,
    Heading,
    Dim,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Span {
    pub ink: Ink,
    pub text: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Block {
    pub indent: usize,
    pub spans: Vec<Span>,
    /// True for lines that came from a fenced code block.
    pub code: bool,
}
    fn event(&mut self, event: Event<'_>, width: usize) {
        match event {
            Event::Start(tag) => self.start(tag),
            Event::End(tag) => self.end(tag, width),
            Event::Text(text) => {
                let ink = if self.code {
                    Ink::Code
                } else if self.bold > 0 {
                    Ink::Heading
                } else if self.strike > 0 {
                    Ink::Strike
                } else if self.italic > 0 {
                    Ink::Italic
                } else {
                    Ink::Plain
                };
                for (index, line) in text.split('\n').enumerate() {
                    if index > 0 {
                        self.flush();
                    }
                    if !line.is_empty() {
                        self.push(ink, line);
                    }
                }
            }
            Event::Code(text) => self.push(Ink::Code, text.as_ref()),
            Event::SoftBreak => self.push(Ink::Plain, " "),
            Event::HardBreak => self.flush(),
            Event::TaskListMarker(done) => self.push(Ink::Dim, if done { "[x] " } else { "[ ] " }),
            Event::Rule => {
                self.flush();
                let indent = self.indent + self.quote * 2;
                self.blocks.push(Block {
                    indent,
                    spans: vec![Span {
                        ink: Ink::Dim,
                        text: "─".repeat(width.max(8)),
                    }],
                    code: false,
                });
            }
            // Raw HTML is dropped rather than shown as tag soup.
            Event::Html(_) | Event::InlineHtml(_) => {}
            _ => {}
        }
    }
